        raise BillingError("invalid_rate", repr(rate_percent))
    if rate_percent < 0 or rate_percent > 100:
        raise BillingError("invalid_rate", repr(rate_percent))
    amount = to_money(amount)
    return round_money(amount * (1 + to_money(rate_percent) / 100))
